import type{RetailLessonContent,RetailSectorContent}from'./retailSectorTypes';type Profile={name:string;products:string;inputs:string;operations:string;channels:string;customers:string;competition:string;technology:string;risks:string;opportunities:string;vietnam:string};const lesson=(description:string,takeaways:string[],title?:string,subtitle?:string):RetailLessonContent=>({description,takeaways,...(title?{title}:{}),...(subtitle?{subtitle}:{})});function build(p:Profile):RetailSectorContent{return{modules:{'How the Industry Works':`Understand the scope, evolution, global structure, Vietnam position, and demand forces shaping ${p.name}.`,'How Value Moves Through the Industry':`Follow ${p.inputs} through sourcing, production, quality, distribution, service, and end use.`,'How Companies Make Money':`Explore product, project, service, channel, and asset economics across ${p.name}.`,'Who Competes—and Why They Win':`Compare competitors on engineering, cost, quality, scale, channels, service, and customer trust.`,'What Is Changing Next':`Assess how technology, customer requirements, sustainability, regulation, and supply networks may reshape the sector.`},lessons:{
'm1-scope':lesson(`Define ${p.name}, its product boundaries, customer applications, and adjacent categories.`,[`Core outputs include ${p.products}.`,`Sector boundaries should follow product function, production capability, and customer application rather than company labels alone.`,`Demand, quality requirements, certification, service intensity, and replacement cycles vary by segment.`],'Industry Definition & Scope','Products, Applications, Customers, and Boundaries'),
'm1-history':lesson(`Trace how engineering, production systems, materials, trade, and customer requirements shaped the modern sector.`,['Mechanization, standardization, global sourcing, automation, and digital design changed cost, speed, quality, and scale.','Production footprints evolve with capability, labor, infrastructure, market access, and resilience requirements.','Historical investment choices explain today’s supplier bases, installed assets, and competitive positions.'],'Industry History & Development','From Craft and Mechanization to Global, Automated Production'),
'm1-global':lesson(`Understand the global market structure, manufacturing hubs, trade flows, specialist clusters, and major participant types.`,[`Global competition combines multinational producers, regional specialists, contract manufacturers, component suppliers, and distributors.`,`Scale matters, but technical specialization, qualification, service, and customer proximity can support focused competitors.`,`Compare market estimates only when product scope, geography, period, currency, and revenue basis are aligned.`],'Global Market Overview','Production Hubs, Trade, Segments, and Industry Structure'),
'm1-vietnam':lesson(`Examine Vietnam’s role in ${p.name}, including domestic demand, production, suppliers, exports, and upgrading needs.`,[p.vietnam,'Vietnam’s position should be evaluated through domestic value added, local capability, quality, productivity, and supplier depth—not exports alone.','Industrial parks, logistics, energy, skills, standards, and customer access influence where investment can scale.'],'Vietnam Market Overview','Domestic Demand, Manufacturing Capability, Trade, and Upgrading'),
'm1-drivers':lesson(`Connect economic cycles, customer investment, materials, labor, technology, trade, regulation, and sustainability to sector change.`,[`Important pressures include ${p.risks}.`,`Demand may follow consumer replacement, construction, industrial investment, energy systems, exports, or customer production cycles.`,`Scenario planning should connect each driver to volume, price, mix, capacity, working capital, and risk.`],'Industry Drivers & External Factors','Demand, Technology, Cost, Trade, Policy, and Sustainability'),
'm2-overview':lesson(`Map the end-to-end chain from ${p.inputs} through ${p.operations}, channels, service, and end use.`,['The chain connects specifications, materials, components, production, quality, logistics, sales, installation or use, and lifecycle support.','Product, information, cash, quality evidence, and risk move through the chain together.','Value is lost when specifications, forecasts, capacity, inventory, and customer requirements are not synchronized.'],'Value Chain Overview','Stages, Participants, Flows, and Control Points'),
'm2-sourcing':lesson(`Explore supplier qualification, material and component economics, contracting, dual sourcing, and traceability.`,[`Key inputs include ${p.inputs}.`,'The lowest purchase price may create higher total cost through defects, delay, scrap, warranty, or unavailable capacity.','Supplier development, specifications, audits, alternatives, and traceability strengthen resilience.'],'Sourcing & Supplier Partnerships','Materials, Components, Qualification, Cost, and Resilience'),
'm2-logistics':lesson(`Follow inbound materials, work in process, finished goods, export logistics, inventory, and planning.`,['Planning must align demand, bills of material, lead times, lot sizes, capacity, and transport constraints.','Inventory buffers variability but consumes cash and can become obsolete, damaged, or non-compliant.','Traceability and logistics design should match product value, size, shelf life, hazard, and service commitments.'],'Supply Chain, Logistics & Inventory','Planning, Material Flow, Traceability, and Working Capital'),
'm2-stores':lesson(`Understand how ${p.operations} convert designs and inputs into reliable output.`,['Manufacturing performance depends on process capability, maintenance, workforce skill, tooling, energy, yield, and bottleneck management.','Quality must be designed into specifications and process controls rather than inspected only at the end.','Automation creates value when it improves throughput, consistency, safety, flexibility, or data quality at acceptable lifecycle cost.'],'Production, Quality & Operations','Engineering, Process Control, Capacity, and Continuous Improvement'),
'm2-customer':lesson(`Trace route-to-market, technical sales, delivery, installation, support, warranty, and customer feedback.`,[`Routes to market include ${p.channels}.`,`Customer value includes product performance, availability, documentation, delivery reliability, service, and total ownership cost.`,`Feedback from sales, field service, returns, and warranty should improve design, sourcing, and production.`],'Distribution, Service & Customer Lifecycle','Sales, Delivery, Installation, Support, and Feedback'),
'm2-value':lesson(`Identify where technical, operational, commercial, and lifecycle value is created and captured.`,['Value may arise from design, intellectual property, sourcing, production yield, customization, certification, brand, distribution, or service.','Revenue does not show value capture without material, conversion, logistics, warranty, channel, and capital costs.','Global scale and local responsiveness should be combined according to product complexity and customer need.'],'Inputs, Outputs & Value Creation','Capability, Quality, Economics, and Lifecycle Value'),
'm3-models':lesson(`Compare branded manufacturing, contract production, original design, project, component, distribution, and service-led models.`,['Business models allocate design ownership, production assets, inventory, customer access, warranty, and market risk differently.','Asset-light models reduce some capital needs but can increase supplier dependency and reduce process control.','A model should be judged by strategic control, contribution, cash conversion, resilience, and customer value.'],'Industry Business Models','Branded, Contract, Project, Component, and Service Models'),
'm3-assortment':lesson(`Structure ${p.products} by application, specification, performance, price, customization, and lifecycle support.`,['Portfolio breadth can increase addressable demand but adds engineering, tooling, inventory, certification, and service complexity.','Platforms and modular designs can create variety while reusing components and processes.','Product exits, upgrades, spare parts, and obsolescence need active lifecycle management.'],'Products, Solutions & Portfolio Architecture','Segments, Specifications, Platforms, and Lifecycle'),
'm3-segments':lesson(`Understand the needs and buying criteria of ${p.customers}.`,['Customer needs differ by performance, compliance, price, volume, delivery, customization, financing, and service.','Consumer, distributor, OEM, project, enterprise, and public buyers may use different decision processes.','Segmentation should connect a real need to an offer, route to market, service model, and economic return.'],'Customer Segments & Buying Needs','Users, OEMs, Distributors, Projects, and Institutions'),
'm3-revenue':lesson(`Map product, project, component, installation, maintenance, spare-parts, licensing, and service revenue against major costs.`,['Revenue quality depends on repeatability, mix, pricing power, contract terms, backlog quality, and collection.','Major costs include materials, labor, energy, depreciation, engineering, quality, logistics, selling, warranty, and compliance.','Margin should be reconciled with working capital, utilization, warranty exposure, and required reinvestment.'],'Revenue Streams & Cost Structure','Pricing, Mix, Conversion Cost, Service, and Cash'),
'm3-store-economics':lesson(`Connect utilization, throughput, yield, downtime, changeovers, labor, energy, and capital to plant economics.`,['Unused capacity can depress returns, while overloaded equipment can damage delivery, quality, maintenance, and safety.','Overall equipment effectiveness is diagnostic only when availability, performance, and quality definitions are consistent.','Investment cases should include ramp-up, training, tooling, maintenance, working capital, and downside scenarios.'],'Plant Economics & Asset Productivity','Capacity, Yield, Throughput, Cost, and Return'),
'm3-ecosystem':lesson(`Identify suppliers, workers, customers, distributors, logistics firms, financiers, standards bodies, regulators, communities, and technology partners.`,['Manufacturing value depends on an ecosystem beyond the factory gate.','Contracts, standards, data, incentives, and governance coordinate participants with different bargaining power.','Responsible operations include worker safety, product quality, environmental management, community impact, and credible claims.'],'Industry Ecosystem & Stakeholders','Partners, Standards, Regulators, Workforce, and Communities'),
'm4-structure':lesson(`Assess rivalry, buyer and supplier power, substitutes, entry barriers, and concentration in ${p.name}.`,[`Competition includes ${p.competition}.`,'Entry barriers may include capital, tooling, know-how, qualification, standards, distribution, installed base, and customer trust.','Competitive intensity differs by product segment, geography, application, and customer switching cost.'],'Industry Competition Structure','Rivalry, Five Forces, Entry Barriers, and Substitutes'),
'm4-players':lesson(`Compare global leaders, regional manufacturers, Vietnamese producers, specialists, importers, and contract suppliers.`,['Parent-company scale should not be confused with product-level strength in every segment.','Benchmark each player on a defined product, geography, customer group, and period.','Local firms may compete through responsiveness, cost, customization, relationships, service, or knowledge of domestic requirements.'],'Key Industry Players','Global Leaders, Vietnam Manufacturers, and Specialists'),
'm4-benchmarking':lesson(`Benchmark competitors with compatible operating, commercial, quality, innovation, and financial measures.`,['Useful criteria include product performance, cost, delivery, quality, capacity, utilization, innovation, channels, service, safety, and cash conversion.','Definitions and denominators must match before comparing defect, productivity, margin, or market measures.','A qualitative scorecard should state evidence, uncertainty, weighting, and strategic purpose.'],'Competitor Benchmarking','Products, Capability, Quality, Cost, Reach, and Economics'),
'm4-success':lesson(`Identify the capabilities required to win sustainably in ${p.name}.`,['Key capabilities include engineering, supplier management, process discipline, quality, talent, cost control, delivery, service, and customer trust.',`Technology priorities include ${p.technology}.`,'Advantage is durable when capabilities reinforce one another and are difficult to imitate economically.'],'Key Success Factors','Engineering, Operations, Quality, Channels, Service, and Trust'),
'm4-swot':lesson(`Connect sector strengths and opportunities with operational weaknesses, competitive threats, and strategic choices.`,[`Opportunity areas include ${p.opportunities}.`,`Material risks include ${p.risks}.`,'Priorities should name owners, investment, milestones, evidence, downside triggers, and contingency actions.'],'Industry SWOT & Strategic Challenges','Capabilities, Risks, Opportunities, and Strategic Priorities'),
'm5-consumer':lesson(`Track changing customer expectations for performance, price, convenience, customization, service, safety, and sustainability.`,['Customers increasingly evaluate total value and lifecycle performance rather than purchase price alone.','Digital research and procurement increase price transparency while making technical evidence and service reputation more visible.','Trend claims should be segmented by customer, application, geography, and purchasing context.'],'Customer & Demand Trends','Changing Applications, Expectations, Replacement, and Value'),
'm5-technology':lesson(`Explore advances in ${p.technology}, digital engineering, automation, analytics, and connected products.`,['Technology creates advantage when it improves customer outcomes or measurable operating capability.','Pilots should define baseline, benefit, data, cybersecurity, skills, maintenance, integration, and scale economics.','New technology can create obsolescence and dependency risks as well as productivity and product opportunities.'],'Technology & Innovation Trends','Digital Engineering, Automation, Data, Materials, and Products'),
'm5-channel':lesson(`Follow shifts in direct sales, distribution, project channels, e-commerce, service networks, and regional supply footprints.`,[`Relevant routes include ${p.channels}.`,'Channel growth should be judged on contribution, service cost, working capital, conflict, and customer ownership.','Regionalization and supplier diversification can improve resilience but may add cost and coordination complexity.'],'Market & Channel Trends','Routes to Market, Digital Sales, Services, and Supply Networks'),
'm5-regulatory':lesson(`Understand how product standards, trade rules, safety, emissions, waste, energy, labor, and customer reporting affect the sector.`,['Compliance requirements vary by product and market and should be verified against current primary sources before decisions.','Lifecycle design, resource efficiency, repair, recycling, and traceability can affect market access and customer preference.','Sustainability claims need defined boundaries, methods, evidence, and governance.'],'Regulatory & Sustainability Trends','Standards, Safety, Trade, Energy, Circularity, and Claims'),
'm5-outlook':lesson(`Assess growth scenarios and strategic opportunities for ${p.name} globally and in Vietnam.`,[`Potential opportunities include ${p.opportunities}.`,'Growth is not guaranteed: demand, capability, capital, competition, policy, infrastructure, talent, and execution determine outcomes.','Use staged investment, scenario ranges, leading indicators, resilience plans, and explicit stop-or-scale criteria.'],'Growth Outlook & Strategic Opportunities','Scenarios, Vietnam Upgrading, Resilience, and Investment Priorities')
}}}
export const MANUFACTURING_SECTOR_CONTENT:Record<string,RetailSectorContent>={
'mfg-electronics':build({name:'Consumer Electronics & Appliances',products:'consumer devices, household appliances, smart products, components, accessories, and lifecycle services',inputs:'semiconductors, displays, motors, batteries, metals, plastics, glass, software, and packaging',operations:'product engineering, tooling, component manufacture, assembly, testing, certification, and quality assurance',channels:'OEM relationships, distributors, modern retail, specialist dealers, e-commerce, installers, and service networks',customers:'households, businesses, OEMs, distributors, retailers, property projects, and service partners',competition:'global brands, original-design manufacturers, contract assemblers, component specialists, local brands, and importers',technology:'connected products, embedded software, AI features, energy efficiency, automation, robotics, and advanced testing',risks:'short product cycles, component concentration, quality and recall exposure, trade controls, currency, channel inventory, and e-waste obligations',opportunities:'higher local design content, supplier upgrading, smart and efficient products, repair and service, components, and export diversification',vietnam:'Vietnam is an important electronics assembly and export base with opportunities to deepen design, component, tooling, supplier, quality, and lifecycle-service capabilities.'}),
'mfg-machinery':build({name:'Machinery & Power Tools',products:'industrial machinery, production equipment, power tools, accessories, consumables, spare parts, and maintenance services',inputs:'steel, castings, motors, bearings, controls, electronics, batteries, tooling, and precision components',operations:'engineering, machining, fabrication, assembly, calibration, testing, commissioning, and field service',channels:'direct technical sales, distributors, dealers, rental partners, project integrators, e-commerce, and aftermarket service',customers:'factories, contractors, workshops, farms, infrastructure projects, distributors, and professional users',competition:'global equipment groups, specialist manufacturers, regional producers, local fabricators, distributors, and low-cost imports',technology:'computer-aided engineering, CNC, robotics, industrial IoT, predictive maintenance, electrification, batteries, and digital service',risks:'capital cycles, imported components, long lead times, utilization swings, safety, counterfeit parts, service coverage, and customer financing',opportunities:'factory automation, local engineering, energy-efficient equipment, aftermarket services, remanufacturing, rental, and SME productivity',vietnam:'Vietnam’s industrial expansion creates demand for machinery and tools while local firms can upgrade from fabrication toward engineering, precision, controls, integration, and service.'}),
'mfg-electrical':build({name:'Electrical & Energy Equipment',products:'cables, transformers, switchgear, motors, power electronics, storage systems, controls, and grid or renewable-energy equipment',inputs:'copper, aluminum, electrical steel, insulation, semiconductors, batteries, enclosures, controls, and certified components',operations:'electrical design, winding, fabrication, assembly, insulation, calibration, high-voltage testing, certification, and commissioning',channels:'utilities, EPC contractors, distributors, project tenders, industrial sales, installers, and service contracts',customers:'utilities, factories, buildings, data centers, renewable projects, infrastructure owners, EPCs, and public buyers',competition:'multinational electrical groups, regional manufacturers, Vietnamese producers, EPC firms, component specialists, and importers',technology:'smart grids, power electronics, digital substations, energy storage, efficient motors, sensors, remote monitoring, and cybersecurity',risks:'commodity prices, project delays, qualification cycles, grid policy, safety, counterfeit components, imported technology, and working capital',opportunities:'grid modernization, renewable integration, storage, data centers, electrification, energy efficiency, localization, and lifecycle service',vietnam:'Vietnam’s expanding power system, industry, buildings, renewables, and data infrastructure create demand alongside requirements for standards, bankable quality, project execution, and local capability.'}),
'mfg-textiles':build({name:'Textiles & Apparel Manufacturing',products:'fibers, yarn, fabric, dyeing and finishing, garments, footwear-related textiles, technical textiles, and manufacturing services',inputs:'natural and synthetic fibers, yarn, dyes, chemicals, trims, accessories, patterns, machinery, water, and energy',operations:'spinning, weaving or knitting, dyeing, finishing, cutting, sewing, washing, inspection, packing, and compliance management',channels:'brand and retailer sourcing, agents, trading firms, export contracts, domestic wholesale, direct sales, and e-commerce partners',customers:'global brands, retailers, sourcing offices, uniform buyers, industrial users, domestic labels, and consumers',competition:'large Asian manufacturing hubs, vertically integrated groups, specialist mills, garment factories, trading firms, and nearshore suppliers',technology:'digital product development, automated cutting, sewing aids, material innovation, traceability, water and energy efficiency, and production analytics',risks:'buyer concentration, short lead times, wage and energy cost, imported materials, compliance, water and chemicals, fashion volatility, and trade rules',opportunities:'higher-value materials, design and development, technical textiles, recycled inputs, traceability, productivity, local material supply, and brand partnerships',vietnam:'Vietnam is a major textile and garment exporter with upgrading opportunities in materials, design, product development, automation, traceability, environmental performance, and customer diversification.'}),
'mfg-building':build({name:'Building Materials & Coatings',products:'cementitious products, glass, ceramics, insulation, boards, construction chemicals, paints, coatings, and engineered building materials',inputs:'minerals, clinker or binders, aggregates, resins, pigments, solvents, additives, glass inputs, energy, and packaging',operations:'formulation, crushing, grinding, firing, mixing, coating production, curing, testing, packaging, and batch quality control',channels:'project specification, contractors, distributors, dealers, architects, developers, home-improvement retail, and direct key accounts',customers:'developers, contractors, infrastructure owners, architects, applicators, dealers, industrial users, and households',competition:'integrated producers, multinational materials groups, domestic manufacturers, regional importers, specialist formulators, and private labels',technology:'low-carbon binders, advanced coatings, insulation, prefabrication, process heat efficiency, alternative fuels, automation, and material traceability',risks:'construction cycles, energy and raw-material cost, overcapacity, logistics radius, project credit, product performance, emissions, and environmental permitting',opportunities:'urbanization, infrastructure, renovation, green buildings, efficient materials, low-carbon production, specialized coatings, and technical service',vietnam:'Vietnam’s construction and infrastructure demand supports a broad materials base, while value upgrading depends on specifications, consistent quality, energy efficiency, logistics, environmental performance, and technical service.'}),
'mfg-packaging':build({name:'Packaging, Labels & Industrial Materials',products:'flexible and rigid packaging, corrugated cases, labels, closures, films, converted paper, protective packaging, and specialized industrial materials',inputs:'paper and board, polymers, aluminum, glass, inks, adhesives, coatings, films, tooling, and recycled feedstock',operations:'material formulation, extrusion, printing, coating, lamination, converting, molding, die-cutting, inspection, and customer qualification',channels:'direct B2B contracts, key-account sales, distributors, converters, design partners, co-packers, and regional export channels',customers:'food and beverage, consumer goods, pharmaceuticals, electronics, industrial manufacturers, logistics firms, retailers, and brand owners',competition:'integrated material producers, global packaging groups, regional converters, label specialists, local printers, and low-cost commodity suppliers',technology:'high-barrier materials, lightweighting, digital printing, smart labels, serialization, recyclable structures, recycled content, automation, and quality vision systems',risks:'resin and paper volatility, customer concentration, food-contact and pharmaceutical compliance, print accuracy, waste rules, substitution, and capital intensity',opportunities:'sustainable redesign, mono-material structures, recycled content, smart and traceable packaging, healthcare, e-commerce protection, and export customers',vietnam:'Vietnam’s manufacturing and export growth supports packaging demand, while suppliers can upgrade through design, material science, printing quality, regulated-market capability, circularity, and regional customer service.'})};
